const year = $('Phase 1 Form').first().json.Year;
const quarterRaw = $('Phase 1 Form').first().json.Quarter;
const quarter = parseInt(quarterRaw.replace('Q', ''));
const bdo_file = $('Upload BDO').first().json.path;
const prev_ma_file = $('Upload MA').first().json.path;
const rent_roll_file = $('Upload Rent Roll').first().json.path;
const sales_tracker_file = $('Upload Sales').first().json.path;
const prev_compliance_file = $('Upload Compliance').first().json.path;

return [{
  json: {
    year: year,
    quarter: quarter,
    bdo_file: bdo_file,
    prev_ma_file: prev_ma_file,
    rent_roll_file: rent_roll_file,
    sales_tracker_file: sales_tracker_file,
    prev_compliance_file: prev_compliance_file
  }
}];

const j = $input.first().json;
if (j.job_id) {
  return [{ json: { job_id: j.job_id } }];
}
let msg = j.message || (j.error && j.error.message);
if (!msg && j.detail != null) {
  msg = typeof j.detail === 'string' ? j.detail : JSON.stringify(j.detail);
}
if (!msg) {
  try { msg = JSON.stringify(j); } catch (e) { msg = 'Unknown error starting Phase 1 job'; }
}
return [{ json: { errors: [String(msg)], message: 'Failed to start Phase 1 job' } }];

