=<!DOCTYPE html>
<html>
<head>
    <title>Phase 1</title>
    <style>
        body{font-family:system-ui,sans-serif;max-width:800px;margin:50px auto;padding:20px;background:#0f172a;color:#e2e8f0}
        .box{background:#1e293b;padding:30px;border-radius:12px;box-shadow:0 4px 20px rgba(0,0,0,0.3)}
        h1{color:#94a3b8;margin-bottom:20px}
        h1.done-ok{color:#4ade80}
        h1.done-fail{color:#f87171}
        .phase-badge{display:inline-block;background:#3b82f6;color:#fff;padding:4px 12px;border-radius:4px;font-size:14px;margin-bottom:15px}
        .btn{display:inline-block;margin:8px 8px 8px 0;padding:12px 20px;background:#3b82f6;color:#fff;text-decoration:none;border-radius:8px;font-weight:500}
        .btn:hover{background:#2563eb}
        .btn-next{background:#22c55e}
        .btn-next:hover{background:#16a34a}
        .stats{background:#0f172a;padding:15px;border-radius:8px;margin:15px 0}
        .next-steps{background:#1e3a5f;padding:20px;border-radius:8px;margin:20px 0;border-left:4px solid #3b82f6}
        .review-note{background:#1e3a5f;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #f59e0b;color:#fcd34d}
        .warn{background:#422006;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #f59e0b;color:#fbbf24}
        .warn ul{margin:8px 0 0 20px;padding:0}
        .warn li{margin:4px 0}
        .ai-pass{background:#052e16;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #4ade80;color:#86efac}
        .ai-issues{background:#1e1b4b;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #818cf8;color:#c7d2fe}
        .ai-skip{background:#1c1917;padding:15px;border-radius:8px;margin:15px 0;border-left:4px solid #78716c;color:#d6d3d1}
        .err{background:#450a0a;padding:20px;border-radius:8px;border-left:4px solid #ef4444}
        a{color:#60a5fa}
    </style>
</head>
<body>
<div class="box" id="box">
    <span class="phase-badge">Phase 1 of 3</span>
    <div id="status">
        <h1>⏳ Processing…</h1>
        <p>Your Management Accounts and Compliance Certificate are being generated. This page updates automatically; AI verification can take several minutes.</p>
        <p id="detail">Connecting…</p>
    </div>
    <div id="result"></div>
</div>
<script>
(function(){
  var API_BASE = "http://16.170.40.114:8000";
  var JOB_ID = "{{ $json.job_id }}";
  var POLL_MS = 5000;
  var MAX_ATTEMPTS = 300;
  var n = 0;
  var detail = document.getElementById("detail");
  var result = document.getElementById("result");
  var statusBox = document.getElementById("status");
  var h1 = statusBox.querySelector("h1");

  function esc(s) {
    if (s == null) return "";
    return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  }

  function renderAI(v) {
    if (!v) return "";
    if (v.status === "PASS") return '<div class="ai-pass"><strong>🤖 AI Verification: PASS</strong><p>All formulas, values, sign conventions, and formatting verified by Claude.</p></div>';
    if (v.status === "ISSUES_FOUND") {
      var notes = esc(v.notes || "Patches applied to Management Accounts file");
      var rev = v.revalidation_passed ? "✅ Passed" : "⚠️ Review needed";
      return '<div class="ai-issues"><strong>🤖 AI Verification: ' + (v.patches_applied || 0) + ' issue(s) auto-corrected</strong><p>' + notes + '</p><p>Re-validation: ' + rev + '</p></div>';
    }
    return '<div class="ai-skip"><strong>🤖 AI Verification: ' + esc(v.status) + '</strong><p>' + esc(v.notes || "") + '</p></div>';
  }

  function showSuccess(data) {
    h1.textContent = "✅ Draft Files Generated!";
    h1.className = "done-ok";
    var exec = (data.execution_time_seconds != null) ? (Number(data.execution_time_seconds).toFixed(1) + " seconds") : "N/A";
    var html = '<div class="stats"><p><strong>Job ID:</strong> ' + esc(data.job_id) + '</p><p><strong>Execution Time:</strong> ' + exec + '</p></div>';
    html += renderAI(data.ai_verification);
    html += '<h3>📥 Download Generated Files for Review:</h3><p>';
    (data.output_files || []).forEach(function(f) {
      var name = f.split("/").pop();
      html += '<a class="btn" href="' + API_BASE + '/api/v1/outputs/' + encodeURIComponent(name) + '" target="_blank">📄 ' + esc(name) + '</a> ';
    });
    html += '</p>';
    if (data.warnings && data.warnings.length) {
      html += '<div class="warn"><strong>⚠️ Data Validation Warning:</strong><ul>';
      data.warnings.forEach(function(w) { html += '<li>' + esc(w) + '</li>'; });
      html += '</ul></div>';
    }
    html += '<div class="review-note"><p><strong>⚠️ Important:</strong> These are draft files. Download and review both the <strong>Management Accounts</strong> and the <strong>Compliance Certificate</strong> before proceeding. Any edits you make will be used in all subsequent phases.</p></div>';
    html += '<div class="next-steps"><h3>📋 Next Steps:</h3><ol><li>Download and review the <strong>Management Accounts</strong></li><li>Download and review the <strong>Compliance Certificate</strong></li><li>Make any necessary edits to both files</li><li>Proceed to <strong>Phase 2</strong> and re-upload the reviewed files</li></ol><a class="btn btn-next" href="/form/generate-word-report">➡️ Continue to Phase 2</a></div><p style="margin-top:25px"><a href="/form/generate-accounts">← Start Over</a></p>';
    result.innerHTML = html;
    statusBox.querySelector("p").style.display = "none";
    detail.style.display = "none";
  }

  function showFail(data) {
    h1.textContent = "❌ Phase 1 Generation Failed";
    h1.className = "done-fail";
    var errs = (data && data.errors) || [];
    var msg = "";
    errs.forEach(function(e) { msg += "<p>• " + esc(e) + "</p>"; });
    if (data && data.message) msg += "<p>• " + esc(data.message) + "</p>";
    result.innerHTML = '<div class="err"><p><strong>Error Details:</strong></p>' + msg + '</div><a class="btn" href="/form/generate-accounts">🔄 Try Again</a>';
    statusBox.querySelector("p").style.display = "none";
    detail.style.display = "none";
  }

  function tick() {
    n++;
    if (n > MAX_ATTEMPTS) {
      detail.textContent = "Timed out waiting for the server. Check n8n execution logs or try again.";
      return;
    }
    detail.textContent = "Checking status… (poll " + n + ")";
    fetch(API_BASE + "/api/v1/jobs/" + encodeURIComponent(JOB_ID))
      .then(function(r) { return r.json(); })
      .then(function(j) {
        if (j.status === "pending" || j.status === "running") {
          setTimeout(tick, POLL_MS);
          return;
        }
        if (j.status === "completed" && j.result) {
          if (j.result.status === "success") showSuccess(j.result);
          else showFail(j.result);
          return;
        }
        if (j.status === "failed") {
          showFail(j.result || { errors: ["Job failed"], message: "" });
          return;
        }
        detail.textContent = "Unexpected status: " + (j.status || "?");
        setTimeout(tick, POLL_MS);
      })
      .catch(function(e) {
        detail.textContent = "Network error: " + (e.message || e);
        setTimeout(tick, POLL_MS);
      });
  }
  tick();
})();
</script>
</body>
</html>

